73	    /** Save a period, keeping the state it is saved in with the sheet's today. */
74	    private Period save(Period period) {
75	        Period saved = periods.saveAndFlush(period);
76	        history.periodSaved(saved.getId(), saved.getSheetId(), saved.getName(), saved.getFrom(), saved.getTo(),
77	                saved.isClosed(), saved.isSoftClosed(), saved.getClosedTotal(), saved.getPersonTotals(),
78	                saved.getPersonCarried());
