107	    /** Generate one period per calendar month from the from-date's month to the to-date's month,
108	     *  each running from the first to the last day of its month and named yyyy-mm; a blank date is
109	     *  the sheet's today. A month whose name is already a period, or whose days overlap a period on
110	     *  the sheet, is left out and the others are still made. Refused when the to-date is before the
111	     *  from-date. Returns how many were made. */
112	    @Transactional
113	    public int generate(String sheetId, String user, LocalDate from, LocalDate to) {
114	        sheets.lock(sheetId);
115	        LocalDate today = sheets.today(sheetId);
116	        LocalDate start = from != null ? from : today;
117	        LocalDate end = to != null ? to : today;
118	        if (end.isBefore(start)) {
119	            throw new PeriodRefusedException("The to-date is before the from-date");
120	        }
121	        List<Period> existing = new ArrayList<>(periods.findBySheetIdOrderByFromAsc(sheetId));
122	        int made = 0;
123	        for (YearMonth month = YearMonth.from(start); !month.isAfter(YearMonth.from(end)); month = month.plusMonths(1)) {
124	            if (addUnlessTaken(sheetId, user, existing, month.toString(), month.atDay(1), month.atEndOfMonth())) {
125	                made++;
126	            }
127	        }
128	        return made;
129	    }
