131	    /** Generate the four calendar quarters of a year, named yyyy-Q1 to yyyy-Q4, each running from the
132	     *  first day of its first month to the last day of its third. A quarter whose name is already a
133	     *  period, or whose days overlap a period on the sheet, is left out and the others are still made.
134	     *  Returns how many were made. */
135	    @Transactional
136	    public int generateQuarters(String sheetId, String user, int year) {
137	        sheets.lock(sheetId);
138	        List<Period> existing = new ArrayList<>(periods.findBySheetIdOrderByFromAsc(sheetId));
139	        int made = 0;
140	        for (int quarter = 1; quarter <= 4; quarter++) {
141	            YearMonth first = YearMonth.of(year, quarter * 3 - 2);
142	            String name = String.format("%04d-Q%d", year, quarter);
143	            if (addUnlessTaken(sheetId, user, existing, name, first.atDay(1), first.plusMonths(2).atEndOfMonth())) {
144	                made++;
145	            }
146	        }
147	        return made;
148	    }
