150	    /** Add a period with no cap from and to a date, as {@link #add} would, unless its name is taken or
151	     *  it overlaps one of the existing periods, which it then joins. Whether it was added. */
152	    private boolean addUnlessTaken(String sheetId, String user, List<Period> existing, String name, LocalDate first,
153	            LocalDate last) {
154	        if (periods.nameInUse(sheetId, name) || existing.stream().anyMatch(p -> p.overlaps(first, last))) {
155	            return false;
156	        }
157	        Period saved = save(new Period(sheetId, name, first, last));
158	        existing.add(saved);
159	        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + name
160	                + " from=" + first + " to=" + last);
161	        return true;
