164	    /** Generate the twelve monthly periods of fiscal year FY<year>, the one whose first day is the first
165	     *  of the sheet's fiscal year start month in that year, exactly as {@link #generate} does. Returns
166	     *  how many were made. */
167	    @Transactional
168	    public int generateFiscalYear(String sheetId, String user, int year) {
169	        LocalDate first = LocalDate.of(year, settings.fiscalStartMonth(sheetId), 1);
170	        return generate(sheetId, user, first, first.plusMonths(11));
171	    }
