173	    /** A steward rolls fiscal year FY<year> over: the twelve monthly periods of FY<year+1> are generated
174	     *  as {@link #generateFiscalYear} does, then each person's open figure at the end of the old year's
175	     *  last period (the dues of their claims that count, due by a day in a period of the old year, and
176	     *  OPEN or PENDING at the end of that last period's last day) is added to their opening balance for
177	     *  the new year's first period (a figure of 0.00 adds nothing and writes nothing). A period belongs to the fiscal year its from-date falls in. Anyone
178	     *  but a steward, or an old year with no periods on the sheet, is refused. Returns how many periods
179	     *  were made. */
180	    @Transactional
181	    public int rollover(String sheetId, String user, int year) {
182	        sheets.lock(sheetId);
183	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
184	            throw new PeriodRefusedException(user + " is not a steward: only a steward rolls the year over");
185	        }
186	        LocalDate oldFirst = LocalDate.of(year, settings.fiscalStartMonth(sheetId), 1);
187	        LocalDate newFirst = oldFirst.plusYears(1);
188	        LocalDate newLast = newFirst.plusYears(1).minusDays(1);
189	        List<Period> oldYear = periods.findBySheetIdOrderByFromAsc(sheetId).stream()
190	                .filter(p -> !p.getFrom().isBefore(oldFirst) && p.getFrom().isBefore(newFirst)).toList();
191	        if (oldYear.isEmpty()) {
192	            throw new PeriodRefusedException("FY" + String.format("%04d", year) + " has no periods");
193	        }
194	        Period last = oldYear.stream().max(Comparator.comparing(Period::getTo)).orElseThrow();
195	        int made = generateFiscalYear(sheetId, user, year + 1);
196	        Period first = periods.findBySheetIdOrderByFromAsc(sheetId).stream()
197	                .filter(p -> !p.getFrom().isBefore(newFirst) && !p.getFrom().isAfter(newLast))
198	                .findFirst()
199	                .orElseThrow(() -> new PeriodRefusedException("FY" + String.format("%04d", year + 1)
200	                        + " has no period to carry into"));
201	
202	        List<Person> everyone = people.findBySheetIdOrderByIdAsc(sheetId);
203	        Map<Long, BigDecimal> open = new LinkedHashMap<>();
204	        everyone.forEach(person -> open.put(person.getId(), BigDecimal.ZERO.setScale(2)));
205	        Map<Long, Person> byId = everyone.stream().collect(Collectors.toMap(Person::getId, Function.identity()));
206	        LocalDate today = sheets.today(sheetId);
207	        Map<Long, ClaimStatus> atEnd = claimService.statusesAsOf(sheetId, last.getTo());
208	        for (Claim claim : claims.findBySheetIdOrderByListedDesc(sheetId)) {
209	            Person person = byId.get(claim.getPersonId());
210	            ClaimStatus then = atEnd.get(claim.getId());
211	            if (person == null || then == null || !then.isOpen()
212	                    || !claim.countsAsOf(then, person.getRetiredFrom(), today)
213	                    || oldYear.stream().noneMatch(p -> p.contains(claim.getDueBy()))) {
214	                continue;
215	            }
216	            BigDecimal due = claimService.dueOf(sheetId, person, claim);
217	            if (due != null) {
218	                open.merge(person.getId(), due, BigDecimal::add);
219	            }
220	        }
221	        for (Person person : everyone) {
222	            BigDecimal amount = open.get(person.getId());
223	            if (amount.signum() == 0) {
224	                continue;
225	            }
226	            first.addOpening(person.getId(), amount);
227	            audit.recordOnCommit("OPENING_SET sheet=" + sheetId + " by=" + user + " name=" + person.getName()
228	                    + " period=" + first.getName() + " amount=" + amount.toPlainString());
229	        }
230	        periods.saveAndFlush(first);
231	        audit.recordOnCommit("ROLLOVER sheet=" + sheetId + " by=" + user + " fy=FY" + String.format("%04d", year)
232	                + " periods=" + made);
233	        return made;
234	    }
