236	    /** Close a period (one soft-closed too, fixing its figures afresh), fixing each person's due-total for it, for everyone on the sheet, and its own
237	     *  due-total, their sum: the figures shown on the claims due by a day in it that counted at the end of its last day (by the
238	     *  status each had then, as its status log records it)
239	     *  (a claim with no figure adds nothing; an OPEN claim dated within its person's hold and not bound by a statement counts for nothing). A period already closed, or a close by a role the sheet's permission matrix does not allow, is refused. */
240	    @Transactional
241	    public Period close(String sheetId, String user, String name) {
242	        sheets.lock(sheetId);
243	        Period period = periods.findBySheetIdAndName(sheetId, name)
244	                .orElseThrow(() -> new NoSuchElementException("No period " + name + " on sheet " + sheetId));
245	        if (!settings.allows(sheetId, user, Permission.CLOSE)) {
246	            throw new PeriodRefusedException("Your role may not close the period " + name);
247	        }
248	        if (period.isClosed()) {
249	            throw new PeriodClosedException("The period " + name + " is already closed");
250	        }
251	        return closeFixing(sheetId, user, period, "");
252	    }
253	
254	    /** Close, as a close by hand would, every open period (not closed or soft-closed) whose to-date plus the sheet's grace days is
255	     *  before the sheet's today, in order of their to-dates, each recorded with auto=yes; nothing when
256	     *  the grace days are blank (off). The sheet's permission matrix governs a close by hand, not this
257	     *  one. Made when the sheet's today is changed, after it is set. */
258	    @Transactional
259	    public void autoClose(String sheetId, String user) {
260	        sheets.lock(sheetId);
261	        Integer grace = settings.graceDays(sheetId);
262	        if (grace == null) {
263	            return;
264	        }
265	        LocalDate today = sheets.today(sheetId);
266	        periods.findBySheetIdOrderByFromAsc(sheetId).stream()
267	                .filter(p -> !p.isClosed() && !p.isSoftClosed() && p.getTo().plusDays(grace).isBefore(today))
268	                .sorted(Comparator.comparing(Period::getTo))
269	                .forEach(p -> closeFixing(sheetId, user, p, " auto=yes"));
270	    }
271	
272	    /** Soft-close a period, fixing each person's due-total for it and its own due-total as a close
273	     *  would, while claims dated in it can still be added and changed. A period already closed or
274	     *  soft-closed, or a soft close by a role the sheet's permission matrix does not allow to close,
275	     *  is refused. */
276	    @Transactional
277	    public Period softClose(String sheetId, String user, String name) {
278	        sheets.lock(sheetId);
279	        Period period = periods.findBySheetIdAndName(sheetId, name)
280	                .orElseThrow(() -> new NoSuchElementException("No period " + name + " on sheet " + sheetId));
281	        if (!settings.allows(sheetId, user, Permission.CLOSE)) {
282	            throw new PeriodRefusedException("Your role may not close the period " + name);
283	        }
284	        if (period.isClosed() || period.isSoftClosed()) {
285	            throw new PeriodClosedException("The period " + name + " is already closed");
286	        }
287	        Map<Long, BigDecimal> personTotals = personTotals(sheetId, period);
288	        BigDecimal total = sum(personTotals);
289	        period.softClose(total, personTotals, personCarried(sheetId, period));
290	        events.publishEvent(new PeriodFixing(period));
291	        Period saved = save(period);
292	        audit.recordOnCommit("PERIOD_SOFT_CLOSED sheet=" + sheetId + " by=" + user + " period=" + name
293	                + " total=" + total.toPlainString());
294	        return saved;
295	    }
296	
297	    private Period closeFixing(String sheetId, String user, Period period, String suffix) {
298	        String name = period.getName();
299	        Map<Long, BigDecimal> personTotals = personTotals(sheetId, period);
300	        BigDecimal total = sum(personTotals);
301	        period.close(total, personTotals, personCarried(sheetId, period));
302	        events.publishEvent(new PeriodFixing(period));
303	        Period saved = save(period);
304	        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user + " period=" + name
305	                + " total=" + total.toPlainString() + suffix);
306	        return saved;
307	    }

